import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Slice;
import org.springframework.data.repository.PagingAndSortingRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AuditLogService {
    private final AuditLogRepository repository;

    public AuditLogService(AuditLogRepository repository) {
        this.repository = repository;
    }

    @Transactional(readOnly = true)
    public Slice<AuditLog> getLogsStreaming(Pageable pageable) {
        // Using Slice instead of Page avoids the expensive COUNT(*) query overhead
        return repository.findAllByStatus("ERROR", pageable);
    }
}

interface AuditLogRepository extends PagingAndSortingRepository<AuditLog, Long> {
    Slice<AuditLog> findAllByStatus(String status, Pageable pageable);
}
